        tween.Completed:Connect(function()
            if thisId ~= animationId or not main.Parent then return end
            animating = false
            main.Visible = open
            miniBtn.Visible = not open
            main.Size = UDim2.fromOffset(width, height)
        end)
        tween:Play()
