    -- ===== speed dipisah: "Speed Aimbot" (semua Aimbot V1-V4) dan "Speed Aimbot Bypas" (semua Aimbot Bypas V1-V4);
    --       barisnya ada di bawah fitur masing-masing (Bypass Version / Aimbot Version) =====
    do
        local function cl(x, m) return math.min(x, m) end
        _G.__KanzApplyAimbotSpeed = function(v, l)
            if v then
                pcall(function() if _G.__KanzAV1SetSpeed then _G.__KanzAV1SetSpeed(cl(v, 120)) end end)
                pcall(function() if _G.__KanzAV2SetSpeed then _G.__KanzAV2SetSpeed(cl(v, 250), nil) end end)
                pcall(function() if _G.__KanzAV3SetSpeed then _G.__KanzAV3SetSpeed(cl(v, 200)) end end)
                pcall(function() if _G.__KanzAV4SetSpeed then _G.__KanzAV4SetSpeed(cl(v, 200), nil) end end)
            end
            if l then
                pcall(function() if _G.__KanzAV2SetSpeed then _G.__KanzAV2SetSpeed(nil, cl(l, 250)) end end)
                pcall(function() if _G.__KanzAV4SetSpeed then _G.__KanzAV4SetSpeed(nil, cl(l, 200)) end end)
            end
        end
        _G.__KanzApplyBypasSpeed = function(v, l)
            if v then
                pcall(function() if _G.__KanzBBSetSpeed then _G.__KanzBBSetSpeed(cl(v, 250), nil) end end)
                pcall(function() if _G.__KanzLagSetSpeed then _G.__KanzLagSetSpeed(cl(v, 250), nil) end end)
                pcall(function() if _G.__KanzBV3SetSpeed then _G.__KanzBV3SetSpeed(cl(v, 250), nil) end end)
                pcall(function() if _G.__KanzBV4SetSpeed then _G.__KanzBV4SetSpeed(cl(v, 200)) end end)
            end
            if l then
                pcall(function() if _G.__KanzBBSetSpeed then _G.__KanzBBSetSpeed(nil, cl(l, 250)) end end)
                pcall(function() if _G.__KanzLagSetSpeed then _G.__KanzLagSetSpeed(nil, cl(l, 250)) end end)
                pcall(function() if _G.__KanzBV3SetSpeed then _G.__KanzBV3SetSpeed(nil, cl(l, 250)) end end)
            end
        end
        -- tampilkan nilai yang sedang aktif setelah pengaturan tersimpan selesai dimuat
        task.spawn(function()
            for _, t in ipairs({1.5, 3, 6}) do
                task.wait(t)
                pcall(function()
                    local av = _G.KanzAimbotV2
                    if av then
                        local anti = av.mode == "Anti Bypass"
                        local n = anti and av.abSpeed or av.speed
                        local l = anti and av.abLaggerSpeed or av.laggerSpeed
                        local b1, b2 = _G.__KanzAimbotSpeedBox, _G.__KanzAimbotLaggerBox
                        if b1 and b1.Parent and not b1:IsFocused() and n then b1.Text = tostring(n) end
                        if b2 and b2.Parent and not b2:IsFocused() and l then b2.Text = tostring(l) end
                    end
                    local bb = _G.__KanzBB
                    if bb then
                        local c1, c2 = _G.__KanzBypasSpeedBox, _G.__KanzBypasLaggerBox
                        if c1 and c1.Parent and not c1:IsFocused() and bb.speed then c1.Text = tostring(bb.speed) end
                        if c2 and c2.Parent and not c2:IsFocused() and bb.laggerSpeed then c2.Text = tostring(bb.laggerSpeed) end
                    end
                end)
            end
        end)
